mapper.select:
select ri.id, ri.room_number, ri.rent, ai.id apartment_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release from room_info ri left join apartment_info ai on ri.apartment_id = ai.id and ai.is_deleted = 0
ri.is_deleted=0 and ri.is_release=1 and ri.id not in( select room_id from lease_agreement where is_deleted=0 and status in(1,2,5,7) )
and ai.province_id=#{queryVo.provinceId}
and ai.city_id=#{queryVo.cityId}
and ai.district_id=#{queryVo.districtId}
and ai.district_name like concat('%', #{queryVo.districtName}, '%')
and ai.name like concat('%', #{queryVo.apartmentName}, '%')
and ri.room_number like concat('%', #{queryVo.roomNumber}, '%')
and ( ai.name like concat('%', #{queryVo.keyword}, '%') or ai.introduction like concat('%', #{queryVo.keyword}, '%') or ai.address_detail like concat('%', #{queryVo.keyword}, '%') or ai.district_name like concat('%', #{queryVo.keyword}, '%') or ai.city_name like concat('%', #{queryVo.keyword}, '%') or ri.room_number like concat('%', #{queryVo.keyword}, '%') )
and ri.id in ( select rav.room_id from room_attr_value rav join attr_value av on rav.attr_value_id = av.id and av.is_deleted = 0 where rav.is_deleted = 0 and av.name like concat('%', #{queryVo.attrName}, '%') )
and ri.id in ( select rf.room_id from room_facility rf join facility_info fi on rf.facility_id = fi.id and fi.is_deleted = 0 where rf.is_deleted = 0 and
fi.name like concat('%', #{facilityName}, '%')
group by rf.room_id having count(distinct case
when fi.name like concat('%', #{facilityName}, '%') then #{facilityName}
end ) = #{facilityCount} )
and ri.id in ( select rl.room_id from room_label rl join label_info li on rl.label_id = li.id and li.is_deleted = 0 where rl.is_deleted = 0 and
li.name like concat('%', #{labelName}, '%')
)
and (ri.rent >= #{queryVo.minRent} and ri.rent <= #{queryVo.maxRent})
and ri.rent >= #{queryVo.minRent}
and ri.rent <= #{queryVo.maxRent}
and ri.id in( select room_id from room_payment_type where is_deleted=0 and payment_type_id=#{queryVo.paymentTypeId} )
order by ri.rent asc
order by ri.rent desc
